// MergeIntervals takes a slice of intervals and merges all overlapping intervals.
// Each interval is represented as a two-element slice [start, end].
// The input is sorted by start time before merging.
func MergeIntervals(in [][]int) [][]int {
	if len(in) == 0 {
		return nil
	}

	// Sort intervals by start time
	sort.Slice(in, func(i, j int) bool {
		return in[i][0] < in[j][0]
	})

	// Initialize result with the first interval
	result := [][]int{in[0]}

	// Iterate through the remaining intervals
	for i := 1; i < len(in); i++ {
		last := result[len(result)-1]
		current := in[i]

		// If the current interval overlaps with the last merged interval,
		// merge them by extending the end if necessary
		if current[0] <= last[1] {
			if current[1] > last[1] {
				last[1] = current[1]
			}
		} else {
			// No overlap, add the current interval as a new merged interval
			result = append(result, current)
		}
	}

	return result
}

